package cn.courselens;
import static org.junit.Assert.*;import org.junit.Test;import org.json.*;import java.io.*;
public class DeepSeekStreamTest {
 private String chunk(JSONObject delta,String finish)throws Exception{return "data: "+new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("delta",delta).put("finish_reason",finish==null?JSONObject.NULL:finish)))+"\n\n";}
 @Test public void plainChatStreamsWithoutJsonRequirements()throws Exception{StringBuilder seen=new StringBuilder();String data=chunk(new JSONObject().put("content","你好，"),null)+chunk(new JSONObject().put("content","我也能回答数学问题。"),"stop")+"data: [DONE]\n";JSONObject r=DeepSeekClient.readStream(new BufferedReader(new StringReader(data)),s->{seen.setLength(0);seen.append(s);});assertEquals("你好，我也能回答数学问题。",r.getString("reply"));assertTrue(r.isNull("operation"));assertEquals(r.getString("reply"),seen.toString());}
 @Test public void toolFragmentsBecomeOneValidatedProposal()throws Exception{String args="{\"type\":\"open_page\",\"value\":{\"page\":\"tasks\"}}";JSONObject first=new JSONObject().put("tool_calls",new JSONArray().put(new JSONObject().put("index",0).put("function",new JSONObject().put("name","propose_operation").put("arguments",args.substring(0,15)))));JSONObject last=new JSONObject().put("tool_calls",new JSONArray().put(new JSONObject().put("index",0).put("function",new JSONObject().put("arguments",args.substring(15)))));JSONObject r=DeepSeekClient.readStream(new BufferedReader(new StringReader(chunk(first,null)+chunk(last,"tool_calls"))),s->{});assertEquals("open_page",r.getJSONObject("operation").getString("type"));}
 @Test public void interruptedReplyIsNotReportedAsComplete()throws Exception{try{DeepSeekClient.readStream(new BufferedReader(new StringReader(chunk(new JSONObject().put("content","半句"),null))),s->{});fail();}catch(IOException expected){}}
}
